from resection import *
def main():
 rng=np.random.default_rng(20261116);X=rng.normal(size=(100,3));X[:,2]+=5;H=pose_delta(np.array([2.,-3.,4.,.2,-.1,.3]));Q=transform(X,H);sol=proper_rigid(X,Q);err=float(np.max(abs(sol-H)));C=np.eye(4);K=np.array([[490,0,319.5],[0,490,179.5],[0,0,1.]]);p,z=project(X,C,K);p1,z1=project(Q,H@C,K);uv=float(np.max(abs(p-p1)));shape=float(np.max(abs(np.linalg.norm(X[1:]-X[:-1],axis=1)-np.linalg.norm(Q[1:]-Q[:-1],axis=1))));v=load(R/'config/REAL_SOURCES.json')[0];a=np.load(v['view_cache']);r=np.load(R/'inputs'/v['group']/'RING.npz');rc=RingConstraint(r['V'],r['F'],a['labels'],a['K']);C=np.array(v['C']);rc.select(C);baseline=rc.residual(C);other=rc.residual(yaw(37)@C);yawdiff=float(np.max(abs(baseline-other)));result=dict(proper_SO3_recovery_max=err,det=float(np.linalg.det(sol[:3,:3])),own_projection_max_px=uv,edge_change_mm=shape,Ring_yaw_residual_change=yawdiff,pass_contracts=bool(err<1e-10 and uv<1e-9 and shape<1e-10 and yawdiff<1e-5));save('metrics/NUMERICAL_CONTRACT_TESTS.json',result);assert result['pass_contracts'],result;print(result)
if __name__=='__main__':main()
